#include <stdio.h>

enum State { IDLE, RUNNING, STOPPED };

int main() {
    enum State state = STOPPED;
    switch (state) {
        case IDLE:
            printf("Idle\n");
            break;
        case RUNNING:
            printf("Running\n");
            break;
        case STOPPED:
            printf("Stopped\n");
            break;
    }
    return 0;
}
